  "brain.py": "\"\"\"Round-robin brain - a pool of identical workers and a rotating interface.\n\n    python brain.py haikus\n    python brain.py \"haiku: the sun\"\n\nEach worker is its own node with its own id, so it is separately addressable\nand separately visible in Prism. The rotation lives in receptors/terminal.py;\nnothing here knows it exists.\n\"\"\"\nimport asyncio\nimport contextlib\nimport signal\n\nfrom cosmonapse import Dendrite, MemorySynapse, connect_synapse, run_brain\n\nfrom config import NAMESPACE, SYNAPSE_URL, WORKERS\nfrom neurons import pool\nfrom receptors import terminal\n\n\ndef build_worker(synapse, worker_id: str) -> Dendrite:\n    \"\"\"One pool member. Same Neuron, different id.\"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=worker_id, role=\"worker\")\n    node.attach_axon(pool.make_axon(worker_id))\n    return node\n\n\ndef build_terminal(synapse) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"terminal-node\", heartbeat_s=0)\n    node.attach_receptor(terminal.RECEPTOR)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    \"\"\"Ctrl-C / SIGTERM cancel the task so run_brain can unwind every node.\"\"\"\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    _stop_on_signals()\n    if SYNAPSE_URL:\n        synapse = await connect_synapse(SYNAPSE_URL)\n    else:\n        synapse = MemorySynapse()      # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(\n            *(build_worker(synapse, w) for w in WORKERS),\n            build_terminal(synapse),\n        )\n    except asyncio.CancelledError:\n        return 0\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
